import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Definizioni di fuso sferico e spicchio sferico","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gk/gkedaa.md","filePath":"lezioni/g_geometria-dello-spazio/gk/gkedaa.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gk/gkedaa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="definizioni-di-fuso-sferico-e-spicchio-sferico" tabindex="-1">Definizioni di fuso sferico e spicchio sferico <a class="header-anchor" href="#definizioni-di-fuso-sferico-e-spicchio-sferico" aria-label="Permalink to “Definizioni di fuso sferico e spicchio sferico”">​</a></h1><p>Chiamiamo <strong>fuso sferico</strong> la parte di superficie sferica compresa fra due semicerchi aventi lo stesso diametro <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>.</p><p>Siccome i due semicerchi giacciono su piani concorrenti nel diametro avremo che fra i due semicerchi si può considerare un angolo diedro e quindi suddividere la sfera in fusi.</p><p>Il fuso più famoso è il fuso orario, ottenuto dividendo la superficie sferica terrestre in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>24</mn></mrow><annotation encoding="application/x-tex">24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">24</span></span></span></span> fusi.</p><p>Importante è pure il fuso di ampiezza <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>1</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">1^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mord"><span class="mord">1</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span> che permette di suddividere la sfera in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>360</mn></mrow><annotation encoding="application/x-tex">360</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">360</span></span></span></span> parti e quindi poter misurare la longitudine prendendo come unità di misura appunto il fuso di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>1</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">1^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mord"><span class="mord">1</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span>.</p><p>Invece, per lo spicchio sferico (di cui un buon esempio è lo spicchio di un&#39;arancia) potremo dire:</p><p>Definiamo <strong>spicchio sferico</strong> la parte di sfera compresa fra due semicerchi aventi lo stesso diametro.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};